import { createServer } from 'node:http';
import { DatabaseSync } from 'node:sqlite';
import { mkdirSync } from 'node:fs';
import { dirname } from 'node:path';

function escapeHtml(value) {
  return String(value).replace(/[&<>"']/g, character => ({
    '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;',
  })[character]);
}

function page(title, content) {
  return `<!doctype html>
<html lang="en"><head><meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>${escapeHtml(title)} · Workboard</title>
<style>
  body { font-family: system-ui, sans-serif; color: #172438; background: #f4f6fa; margin: 0; }
  main { max-width: 720px; margin: 48px auto; padding: 24px; background: white; border-radius: 12px; }
  h1 { margin-top: 0; }
  label { display: block; margin-bottom: 8px; font-weight: 600; }
  input, button, select { font: inherit; padding: 10px 14px; border-radius: 6px; }
  input { border: 1px solid #8794a8; max-width: 100%; box-sizing: border-box; }
  button { background: #244db2; color: white; border: 0; cursor: pointer; }
  button:focus-visible, input:focus-visible, select:focus-visible { outline: 3px solid #e59e16; outline-offset: 3px; }
  .project-row { display: flex; align-items: center; justify-content: space-between; gap: 16px; padding: 16px 0; border-bottom: 1px solid #dbe1eb; }
  .project-name { overflow-wrap: anywhere; min-width: 0; }
  .project-row form { flex-shrink: 0; }
  .task-row { display: flex; align-items: center; gap: 12px; padding: 16px 0; border-bottom: 1px solid #dbe1eb; }
  .task-row label { margin: 0; overflow-wrap: anywhere; }
  .task-controls { margin-top: 24px; }
  [role="alert"] { color: #a01616; }
  @media (max-width: 600px) { main { margin: 16px; } }
</style></head><body><main>${content}</main></body></html>`;
}

async function readForm(request) {
  const chunks = [];
  let size = 0;
  for await (const chunk of request) {
    size += chunk.length;
    if (size > 65536) {
      const error = new Error('Request too large');
      error.status = 413;
      throw error;
    }
    chunks.push(chunk);
  }
  return new URLSearchParams(Buffer.concat(chunks).toString('utf8'));
}

export function createApplication(databasePath) {
  mkdirSync(dirname(databasePath), { recursive: true });
  const database = new DatabaseSync(databasePath);
  database.exec(`CREATE TABLE IF NOT EXISTS projects (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    name TEXT NOT NULL
  )`);
  database.exec(`PRAGMA foreign_keys = ON;
    CREATE TABLE IF NOT EXISTS tasks (
      id INTEGER PRIMARY KEY AUTOINCREMENT,
      project_id INTEGER NOT NULL REFERENCES projects(id),
      title TEXT NOT NULL,
      completed INTEGER NOT NULL DEFAULT 0 CHECK (completed IN (0, 1))
    );
    CREATE INDEX IF NOT EXISTS tasks_project_id ON tasks(project_id);`);
  const listTasks = database.prepare('SELECT id, title, completed FROM tasks WHERE project_id = ? ORDER BY id');
  const insertTask = database.prepare('INSERT INTO tasks (project_id, title) VALUES (?, ?)');
  const updateTask = database.prepare('UPDATE tasks SET completed = ? WHERE id = ? AND project_id = ?');
  const listProjects = database.prepare('SELECT id, name FROM projects ORDER BY id');
  const getProject = database.prepare('SELECT id, name FROM projects WHERE id = ?');
  const insertProject = database.prepare('INSERT INTO projects (name) VALUES (?)');

  function projectsPage(error = '') {
    const rows = listProjects.all().map(project => `
      <div class="project-row" data-testid="project-row">
        <span class="project-name">${escapeHtml(project.name)}</span>
        <form action="/projects/${project.id}" method="get"><button type="submit">Open project</button></form>
      </div>`).join('');
    return page('Projects', `<h1>Workboard</h1>
      ${error ? `<p role="alert">${escapeHtml(error)}</p>` : ''}
      <form action="/projects" method="post">
        <label for="project-name">Project name</label>
        <input id="project-name" name="name" type="text">
        <button type="submit">Create project</button>
      </form>
      <section aria-label="Projects">${rows}</section>`);
  }

  function taskFilter(value) {
    return ['All', 'Open', 'Completed'].includes(value) ? value : 'All';
  }

  function projectPage(project, filter, error = '') {
    const path = `/projects/${project.id}`;
    const rows = listTasks.all(project.id)
      .filter(task => filter === 'All' || Boolean(task.completed) === (filter === 'Completed'))
      .map(task => `<div class="task-row" data-testid="task-row">
        <form action="${path}/tasks/${task.id}" method="post">
          <input type="hidden" name="filter" value="${filter}">
          <input id="task-${task.id}" type="checkbox" name="completed" value="1"
            aria-label="Complete ${escapeHtml(task.title)}" ${task.completed ? 'checked' : ''}
            onchange="this.form.requestSubmit()">
          <label for="task-${task.id}">${escapeHtml(task.title)}</label>
        </form>
      </div>`).join('');
    return page(project.name, `<h1>${escapeHtml(project.name)}</h1>
      <form action="/" method="get"><button type="submit">Projects</button></form>
      ${error ? `<p role="alert">${escapeHtml(error)}</p>` : ''}
      <form class="task-controls" action="${path}/tasks" method="post">
        <input type="hidden" name="filter" value="${filter}">
        <label for="task-title">Task title</label>
        <input id="task-title" name="title" type="text">
        <button type="submit">Create task</button>
      </form>
      <form class="task-controls" action="${path}" method="get">
        <label for="task-filter">Task filter</label>
        <select id="task-filter" name="filter" onchange="this.form.requestSubmit()">
          ${['All', 'Open', 'Completed'].map(option => `<option${filter === option ? ' selected' : ''}>${option}</option>`).join('')}
        </select>
      </form>
      <section aria-label="Tasks">${rows}</section>`);
  }

  function html(response, status, content) {
    response.writeHead(status, { 'Content-Type': 'text/html; charset=utf-8' });
    response.end(content);
  }

  const server = createServer(async (request, response) => {
    try {
      const { pathname, searchParams } = new URL(request.url, 'http://localhost');
      if (request.method === 'GET' && pathname === '/health') {
        response.writeHead(200, { 'Content-Type': 'application/json' });
        response.end(JSON.stringify({ status: 'ok' }));
      } else if (request.method === 'GET' && pathname === '/') {
        html(response, 200, projectsPage());
      } else if (request.method === 'POST' && pathname === '/projects') {
        const form = await readForm(request);
        const name = (form.get('name') ?? '').trim();
        if (!name) {
          html(response, 422, projectsPage('Project name is required'));
          return;
        }
        insertProject.run(name);
        response.writeHead(303, { Location: '/' });
        response.end();
      } else if (request.method === 'GET' && /^\/projects\/\d+$/.test(pathname)) {
        const id = Number(pathname.split('/')[2]);
        const project = Number.isSafeInteger(id) ? getProject.get(id) : undefined;
        if (!project) {
          html(response, 404, page('Not found', '<h1>Project not found</h1><form action="/"><button>Projects</button></form>'));
          return;
        }
        html(response, 200, projectPage(project, taskFilter(searchParams.get('filter'))));
      } else if (request.method === 'POST' && /^\/projects\/\d+\/tasks(?:\/\d+)?$/.test(pathname)) {
        const [, , projectId, , taskId] = pathname.split('/');
        const id = Number(projectId);
        const project = Number.isSafeInteger(id) ? getProject.get(id) : undefined;
        if (!project) {
          html(response, 404, page('Not found', '<h1>Project not found</h1>'));
          return;
        }
        const form = await readForm(request);
        const filter = taskFilter(form.get('filter'));
        if (taskId === undefined) {
          const title = (form.get('title') ?? '').trim();
          if (!title) {
            html(response, 422, projectPage(project, filter, 'Task title is required'));
            return;
          }
          insertTask.run(id, title);
        } else {
          const taskNumber = Number(taskId);
          const result = Number.isSafeInteger(taskNumber)
            ? updateTask.run(form.get('completed') === '1' ? 1 : 0, taskNumber, id)
            : undefined;
          if (!result?.changes) {
            html(response, 404, page('Not found', '<h1>Task not found</h1>'));
            return;
          }
        }
        response.writeHead(303, { Location: `/projects/${id}?filter=${filter}` });
        response.end();
      } else {
        html(response, 404, page('Not found', '<h1>Page not found</h1>'));
      }
    } catch (error) {
      if (!error.status) console.error(error);
      if (!response.headersSent) {
        html(response, error.status ?? 500, page('Error', '<h1>Unable to complete request</h1>'));
      } else {
        response.end();
      }
    }
  });
  server.on('close', () => database.close());
  return server;
}

import { createApplication } from './app.js';

const port = Number(process.env.PORT ?? 8080);
if (!Number.isInteger(port) || port < 0 || port > 65535) {
  throw new Error('PORT must be an integer between 0 and 65535');
}
const server = createApplication(process.env.DB_PATH ?? './data/workboard.sqlite');
server.listen(port, '0.0.0.0', () => {
  console.log(`Workboard listening on port ${server.address().port}`);
});
for (const signal of ['SIGINT', 'SIGTERM']) {
  process.on(signal, () => server.close());
}

import test from 'node:test';
import assert from 'node:assert/strict';
import { mkdtemp, rm } from 'node:fs/promises';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import { once } from 'node:events';
import { createApplication } from '../app.js';

test('tasks validate, filter, remain project-owned, and persist completion', async () => {
  const directory = await mkdtemp(join(tmpdir(), 'workboard-tasks-'));
  const databasePath = join(directory, 'workboard.sqlite');
  let server;
  let url;
  async function start() {
    server = createApplication(databasePath);
    server.listen(0, '127.0.0.1');
    await once(server, 'listening');
    url = `http://127.0.0.1:${server.address().port}`;
  }
  async function stop() {
    const closed = once(server, 'close');
    server.close();
    await closed;
    server = undefined;
  }
  const get = async path => (await fetch(url + path)).text();
  const post = (path, values) => fetch(url + path, {
    method: 'POST', body: new URLSearchParams(values), redirect: 'manual',
  });
  const titles = html => [...html.matchAll(/<label for="task-\d+">(.*?)<\/label>/g)].map(match => match[1]);
  try {
    await start();
    await post('/projects', { name: 'Alpha' });
    await post('/projects', { name: 'Beta' });
    let html = await get('/projects/1');
    assert.match(html, /<label for="task-title">Task title<\/label>/);
    assert.match(html, />Create task<\/button>/);
    assert.match(html, /<label for="task-filter">Task filter<\/label>/);
    assert.match(html, /<option selected>All<\/option><option>Open<\/option><option>Completed<\/option>/);
    for (const title of ['', ' \t\n ']) {
      const response = await post('/projects/1/tasks', { title });
      assert.equal(response.status, 422);
      html = await response.text();
      assert.match(html, /role="alert">Task title is required/);
      assert.deepEqual(titles(html), []);
    }
    for (const title of ['  First  ', 'Second <&"', 'Third']) {
      assert.equal((await post('/projects/1/tasks', { title })).status, 303);
    }
    await post('/projects/2/tasks', { title: 'Other project' });
    html = await get('/projects/1');
    assert.deepEqual(titles(html), ['First', 'Second &lt;&amp;&quot;', 'Third']);
    assert.equal((html.match(/data-testid="task-row"/g) ?? []).length, 3);
    assert.match(html, /aria-label="Complete First"/);
    assert.match(html, /aria-label="Complete Second &lt;&amp;&quot;"/);
    assert.doesNotMatch(html, / checked/);
    assert.deepEqual(titles(await get('/projects/2')), ['Other project']);
    assert.equal((await post('/projects/2/tasks/1', { completed: '1' })).status, 404);
    assert.equal((await post('/projects/999/tasks', { title: 'Missing' })).status, 404);
    const response = await post('/projects/1/tasks/2', { completed: '1', filter: 'Open' });
    assert.equal(response.status, 303);
    assert.equal(response.headers.get('location'), '/projects/1?filter=Open');
    assert.deepEqual(titles(await get('/projects/1?filter=Open')), ['First', 'Third']);
    html = await get('/projects/1?filter=Completed');
    assert.deepEqual(titles(html), ['Second &lt;&amp;&quot;']);
    assert.match(html, / checked/);
    assert.match(html, /<option selected>Completed/);
    assert.equal(titles(await get('/projects/1?filter=invalid')).length, 3);
    const saved = await get('/projects/1');
    await stop();
    await start();
    assert.equal(await get('/projects/1'), saved);
    await post('/projects/1/tasks/2', {});
    assert.deepEqual(titles(await get('/projects/1?filter=Completed')), []);
    assert.equal(titles(await get('/projects/1?filter=Open')).length, 3);
    assert.equal((await post('/projects/1/tasks', { title: ' ' })).status, 422);
    assert.equal(titles(await get('/projects/1')).length, 3);
    await stop();
    await start();
    assert.deepEqual(titles(await get('/projects/1?filter=Completed')), []);
  } finally {
    if (server) await stop();
    await rm(directory, { recursive: true, force: true });
  }
});

